    else:
        self._match_text_seq("ALWAYS")
        this = self.expression(exp.GeneratedAsIdentityColumnConstraint, this=True)

    self._match(TokenType.ALIAS)

    if self._match_text_seq("ROW"):
        start = self._match_text_seq("START")
        if not start:
