                persisted = True
            elif self._match_text_seq("VIRTUAL"):
                persisted = False

            if persisted is not None:
                return self.expression(
                    exp.ComputedColumnConstraint, 
                    this=this.expression, 
                    persisted=persisted
                )

    return this

